import pandas as pd


def long_format(wide):
    """Reshape the table of home runs per year from wide to long format."""
    groups = {"year": ["year1", "year2"], "hr": ["hr1", "hr2"]}
    return pd.lreshape(wide, groups)
```

```python
import pandas as pd


def long_format(wide):
    """Reshape the table of home runs per year from wide to long format."""
    groups = {"year": ["year1", "year2"], "hr": ["hr1", "hr2"]}
    return pd.wide_to_long(
        wide,
        stubnames=["year", "hr"],
        i=[col for col in wide.columns if col not in ["year1", "year2", "hr1", "hr2"]],
        j="obs",
    ).reset_index()
```

