```python
import numpy as np


def is_ragged(rows):
    """Return True if the rows differ in length, using NumPy's warning/error about ragged input."""
    VisibleDeprecationWarning = getattr(
        np.exceptions, "VisibleDeprecationWarning", DeprecationWarning
    )
    try:
        np.asarray(rows)
    except (VisibleDeprecationWarning, ValueError):
        return True
    return False
```

```python
import numpy as np


def is_ragged(rows):
    """Return True if the rows differ in length, using NumPy's warning about ragged input."""
    VisibleDeprecationWarning = getattr(
        np.exceptions, "VisibleDeprecationWarning", getattr(np, "VisibleDeprecationWarning", Warning)
    )
    try:
        np.asarray(rows)
    except (VisibleDeprecationWarning, ValueError):
        return True
    return False
```

